@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#07141b;--cream:#e9e9dc;--muted:#a3b2b1;--cyan:#83e9dc;--gold:#e5c992;--line:rgba(222,239,231,.2);--mono:'DM Mono',monospace;--sans:'Manrope',sans-serif}*{box-sizing:border-box}html,body,#game{width:100%;height:100%;margin:0;overflow:hidden}body{background:#07141b;color:var(--cream);font-family:var(--sans);user-select:none;-webkit-user-select:none;touch-action:none}button{font:inherit;color:inherit;cursor:pointer}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.grain,.vignette{position:absolute;inset:0;pointer-events:none}.grain{z-index:2;opacity:.075;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E");mix-blend-mode:soft-light}.vignette{z-index:2;background:radial-gradient(ellipse at 50% 46%,transparent 35%,rgba(2,10,14,.38) 100%);pointer-events:none}.screen{position:absolute;z-index:4;inset:0;transition:opacity .8s,visibility .8s}.hidden{opacity:0!important;visibility:hidden!important;pointer-events:none!important}.title-screen{display:flex;flex-direction:column;justify-content:space-between;padding:clamp(24px,5vw,68px);background:linear-gradient(90deg,rgba(4,13,18,.84),rgba(4,13,18,.45) 50%,rgba(4,13,18,.05)),linear-gradient(0deg,rgba(4,13,18,.58),transparent 30%,rgba(4,13,18,.12));z-index:5}.title-top,.title-bottom{display:flex;align-items:flex-start;justify-content:space-between}.brand-mark{font-size:27px;font-weight:800;letter-spacing:-3px;color:#eff4e8}.brand-mark span{color:var(--cyan);font-weight:400}.brand-mark.small{font-size:20px;letter-spacing:-2px}.edition,.title-bottom,.eyebrow,.title-meta,.objective small,.status-pills,.icon-button small,.controls-hint,.timeline-head,.timeline-object,.time-rail small,.timeline-foot,.dialogue-content>small,.panel-kicker,.loading p{font:10px var(--mono);letter-spacing:.13em}.edition{text-align:right;line-height:1.75;color:#b1bfba}.title-copy{margin-left:8%;margin-top:-2vh}.eyebrow{display:flex;align-items:center;gap:12px;color:#b8cfca}.eyebrow i,.pulse{display:inline-block;width:6px;height:6px;background:var(--cyan);border-radius:50%;box-shadow:0 0 13px var(--cyan)}h1{font-size:clamp(58px,9vw,132px);line-height:.96;letter-spacing:-.085em;font-weight:500;margin:25px 0 19px}h1 em{font-family:Georgia,serif;font-weight:400;color:var(--cyan);letter-spacing:-.075em}.title-copy p{font-size:15px;line-height:1.8;color:#c2d0cb;margin:0 0 28px}.primary-button{background:#d6e8df;color:#101c20;border:0;padding:17px 22px;min-width:222px;display:flex;justify-content:space-between;align-items:center;font:11px var(--mono);letter-spacing:.09em;transition:.25s}.primary-button:hover{background:#a2eee2;transform:translateY(-2px)}.primary-button span{font-size:17px}.title-meta{margin-top:19px;color:#90a29e;font-size:9px}.title-meta span{color:var(--cyan);padding:0 8px}.title-bottom{font-size:9px;color:#a6b3ae;align-items:flex-end}.loading{position:absolute;z-index:10;inset:0;background:#07141b;display:flex;flex-direction:column;align-items:center;justify-content:center;transition:opacity .7s}.loading-mark{font-size:34px;font-weight:800;letter-spacing:-4px}.loading-mark span{color:var(--cyan)}.loading p{color:#99aaa5;margin:20px 0}.loading-line{width:150px;height:1px;background:#31434a}.loading-line i{display:block;width:40%;height:100%;background:var(--cyan);animation:load 1.2s ease-in-out infinite}@keyframes load{from{transform:translateX(-100%)}to{transform:translateX(250%)}}
.hud{position:absolute;z-index:3;inset:0;transition:opacity .45s}.topbar{position:absolute;left:0;right:0;top:0;padding:27px 38px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(4,13,17,.6),transparent)}.hud-brand{display:flex;gap:15px;align-items:center}.hud-brand>div{display:flex;flex-direction:column;gap:5px}.hud-brand b{font-size:11px;letter-spacing:.11em}.hud-brand small{font:9px var(--mono);letter-spacing:.12em;color:#a4b8b2}.hud-brand small i{font-style:normal;color:var(--cyan)}.top-actions{display:flex;gap:26px}.icon-button{border:0;background:transparent;display:flex;flex-direction:column;gap:5px;align-items:center;opacity:.8}.icon-button:hover{color:var(--cyan);opacity:1}.icon-button>span{font-size:21px}.icon-button small{font-size:8px}.objective{position:absolute;top:105px;left:38px;display:flex;align-items:center;gap:12px;padding:12px 16px 12px 0;border-top:1px solid var(--line);min-width:230px}.objective-icon{color:var(--cyan);font-size:19px}.objective>div{display:flex;flex-direction:column;gap:5px}.objective small{font-size:8px;color:#a9b8b4}.objective b{font-weight:600;font-size:12px}.status-pills{position:absolute;right:38px;top:109px;display:flex;gap:18px;color:#a4b5b0;font-size:8px}.status-pills span{display:flex;align-items:center;gap:7px}.status-pills b{color:#e8eee7;font-weight:500}.status-pills .pulse{width:5px;height:5px}.controls-hint{position:absolute;bottom:28px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#a7b6b1;font-size:8px}.controls-hint span{color:#eff1e8}.controls-hint i{color:var(--cyan);font-style:normal;margin:0 7px}.crosshair{position:absolute;z-index:3;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);opacity:.8}.crosshair i{position:absolute;background:rgba(226,245,236,.75)}.crosshair i:first-child{width:1px;height:14px;left:8px;top:2px}.crosshair i:last-child{height:1px;width:14px;top:8px;left:2px}.interact-prompt{position:absolute;top:58%;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;background:rgba(5,17,22,.78);border:1px solid var(--line);padding:9px 13px;font-size:11px;backdrop-filter:blur(8px)}.keycap{border:1px solid #8a9e97;padding:3px 6px;font:10px var(--mono);color:var(--cyan)}.toast{position:absolute;left:50%;top:23%;transform:translate(-50%,-10px);padding:11px 16px;border:1px solid rgba(131,233,220,.28);background:rgba(5,17,22,.86);font:10px var(--mono);letter-spacing:.08em;color:var(--cyan);opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.timeline-toggle{position:absolute;right:35px;bottom:38px;display:flex;align-items:center;gap:10px;background:rgba(7,21,26,.76);border:1px solid rgba(200,225,215,.27);padding:10px 15px;text-align:left;font:8px var(--mono);letter-spacing:.09em;color:#b8c5bd;backdrop-filter:blur(8px)}.timeline-toggle:hover{border-color:var(--cyan)}.timeline-toggle b{color:var(--cyan);font-weight:500}.time-glyph{font-size:22px;color:var(--cyan)}.timeline{position:absolute;right:35px;bottom:102px;width:min(350px,calc(100vw - 30px));padding:17px 19px 14px;background:rgba(7,20,25,.94);border:1px solid rgba(168,222,210,.32);box-shadow:0 18px 70px #0008;backdrop-filter:blur(18px);transition:opacity .25s}.timeline-head{display:flex;justify-content:space-between;color:#91aaa4;font-size:9px}.timeline-head button,.dialogue>button{border:0;background:none;color:#b9c9c1;font-size:21px;line-height:12px}.timeline-object{margin-top:15px;font-size:10px;color:#e8eee7;letter-spacing:.1em}.time-rail{position:relative;display:flex;justify-content:space-between;margin:16px 0 13px}.time-rail:before{content:'';position:absolute;left:10%;right:10%;top:10px;height:1px;background:#546762}.time-rail button{position:relative;z-index:1;border:0;background:none;color:#91a19b;display:flex;align-items:center;flex-direction:column;gap:6px;font:10px var(--mono);padding:0 8px}.time-rail button:before{content:'';width:8px;height:8px;border:1px solid #9caea6;background:#0a1a1e;border-radius:50%}.time-rail button.selected{color:var(--cyan)}.time-rail button.selected:before{background:var(--cyan);border-color:var(--cyan);box-shadow:0 0 13px #83e9dc}.time-rail small{font-size:8px;color:#889a94}.time-description{font-size:11px;line-height:1.6;color:#c2cec6;min-height:35px;border-top:1px solid #ffffff20;padding-top:10px}.timeline-foot{display:flex;justify-content:space-between;color:#788b85;font-size:8px;margin-top:8px}.dialogue{position:absolute;bottom:7%;left:50%;transform:translateX(-50%);width:min(650px,calc(100vw - 36px));padding:21px 24px;display:flex;gap:17px;background:rgba(7,19,24,.94);border:1px solid rgba(131,233,220,.34);box-shadow:0 12px 50px #0008;backdrop-filter:blur(18px)}.dialogue-avatar{width:39px;height:39px;border:1px solid var(--cyan);border-radius:50%;display:grid;place-items:center;font:18px var(--mono);color:var(--cyan);flex:0 0 auto}.dialogue-content{flex:1}.dialogue-content>small{font-size:9px;color:var(--cyan)}.dialogue-content p{font-size:13px;line-height:1.75;color:#e0e7dc;margin:10px 22px 14px 0}.dialogue-choices{display:flex;gap:8px;flex-wrap:wrap}.dialogue-choices button{background:transparent;border:1px solid #ffffff36;padding:8px 11px;color:#c1d0c8;font-size:10px}.dialogue-choices button:hover{border-color:var(--cyan);color:var(--cyan)}.dialogue>button{position:absolute;right:15px;top:14px}.panel{position:absolute;z-index:6;right:0;top:0;bottom:0;width:min(470px,100%);padding:42px 38px;background:rgba(6,18,23,.96);border-left:1px solid #c5e0d534;box-shadow:-30px 0 80px #0005;transition:transform .35s,opacity .35s;overflow:auto;backdrop-filter:blur(18px)}.panel-close{position:absolute;right:29px;top:27px;background:none;border:0;font-size:24px;color:#aec1b9}.panel-kicker{color:#a7b6b0;font-size:9px}.panel-kicker span{color:var(--cyan);margin:0 8px}.panel-kicker b{font-weight:400;color:var(--cyan)}.panel h2{font-size:34px;letter-spacing:-.06em;font-weight:500;margin:28px 0 24px}.note-card{padding:17px 0;border-top:1px solid #d5e7db24}.note-card small{font:9px var(--mono);letter-spacing:.1em;color:var(--cyan)}.note-card h3{margin:8px 0;font-size:14px;font-weight:600}.note-card p{color:#abbab2;font-size:12px;line-height:1.8;margin:0}.map-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.map-node{min-height:102px;border:1px solid #d5e7db25;padding:15px;display:flex;flex-direction:column;justify-content:space-between;background:#ffffff04}.map-node b{font-size:12px;font-weight:600}.map-node small{font:8px var(--mono);color:#92aaa2;letter-spacing:.09em}.map-node.active{border-color:#83e9dc85;background:#83e9dc0d}.map-node.locked{opacity:.42}.settings-row{padding:16px 0;border-top:1px solid #d5e7db24;display:flex;justify-content:space-between;align-items:center;font-size:12px}.settings-row small{color:#a7b6b0}.settings-row select,.settings-row input{accent-color:#83e9dc;background:#10242a;color:#e9e9dc;border:1px solid #ffffff35;padding:7px}.setting-actions{display:flex;gap:8px;margin-top:24px}.setting-actions button{background:transparent;border:1px solid #ffffff35;padding:10px 13px;font-size:10px}.setting-actions button:hover{border-color:var(--cyan)}
.mobile-controls{display:none}.joystick{position:absolute;bottom:26px;left:24px;width:126px;height:126px;display:flex;align-items:center;justify-content:center}.joy-ring{width:88px;height:88px;border-radius:50%;border:1px solid #d8e9df55;background:#06151a45;display:grid;place-items:center;backdrop-filter:blur(4px)}#joy-knob{width:39px;height:39px;border-radius:50%;border:1px solid #83e9dc99;background:#83e9dc33}.joystick>small{position:absolute;bottom:-4px;font:8px var(--mono);letter-spacing:.1em;color:#d4dfd8}.mobile-actions{position:absolute;right:20px;bottom:26px;display:grid;grid-template-columns:54px 54px;gap:10px}.mobile-actions button{height:52px;background:#07191ec2;border:1px solid #d8e9df55;border-radius:50%;font:9px var(--mono);color:#e8f3e9;backdrop-filter:blur(6px)}.mobile-actions #mobile-use{grid-column:2;grid-row:1/3;height:65px;width:65px;border-color:#83e9dc99;color:var(--cyan)}.mobile-actions #mobile-run{grid-column:1;grid-row:2}.mobile-actions #mobile-jump{grid-column:1;grid-row:1}.timeline-open .controls-hint{display:none}
@media(max-width:700px){.title-screen{padding:26px 23px}.title-copy{margin:0 0 8vh 3%;}.title-copy h1{font-size:clamp(55px,15vw,86px)}.title-copy p{font-size:13px}.edition,.title-bottom{font-size:8px}.title-bottom span:last-child{display:none}.topbar{padding:18px 17px}.top-actions{gap:12px}.icon-button small{font-size:7px}.hud-brand{gap:9px}.hud-brand b{font-size:9px}.hud-brand small{font-size:7px}.objective{top:83px;left:18px;min-width:0}.status-pills{right:17px;top:91px;gap:8px;font-size:7px;flex-direction:column;align-items:flex-end}.controls-hint{display:none}.mobile-controls{display:block}.timeline-toggle{right:18px;bottom:169px;padding:8px 11px}.timeline{right:12px;bottom:227px}.interact-prompt{top:56%;font-size:10px}.dialogue{bottom:15px;padding:17px}.dialogue-content p{font-size:12px}.panel{padding:36px 25px}.panel h2{font-size:29px}.crosshair{top:48%}}
@media(min-width:701px) and (pointer:coarse){.mobile-controls{display:block}.controls-hint{display:none}.timeline-toggle{bottom:175px}}
@media(prefers-reduced-motion:reduce){*{animation-duration:.01ms!important;transition-duration:.01ms!important}}

import * as THREE from 'three';

const $ = (s) => document.querySelector(s);
const ui = {
  title: $('#title-screen'), hud: $('#hud'), loading: $('#loading'), start: $('#start-button'),
  crosshair: $('#crosshair'), objective: $('#objective-text'), prompt: $('#interact-prompt'), promptLabel: $('#interact-label'),
  timeline: $('#timeline'), timelineObject: $('#timeline-object'), timeDescription: $('#time-description'), toast: $('#toast'),
  dialogue: $('#dialogue'), speaker: $('#speaker'), dialogueText: $('#dialogue-text'), choices: $('#dialogue-choices'),
  panel: $('#panel'), panelLabel: $('#panel-label'), panelTitle: $('#panel-title'), panelContent: $('#panel-content'),
  artifactCount: $('#artifact-count')
};
const scene = new THREE.Scene();
scene.background = new THREE.Color('#0b2228');
scene.fog = new THREE.FogExp2('#0b2228', .023);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, .1, 150);
const renderer = new THREE.WebGLRenderer({canvas: $('#world'), antialias: true, alpha: false, powerPreference: 'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;

const clock = new THREE.Clock();
const player = {pos: new THREE.Vector3(0,0,6), velocityY: 0, yaw: Math.PI, pitch: -.08, speed: 4.2, grounded: true};
const held = new Set();
const interactables = [];
const particles = [];
let activeTarget = null, currentRegion = 0, started = false, dialogueOpen = false, panelOpen = false;
let artifacts = new Set(JSON.parse(localStorage.getItem('mot-artifacts') || '[]'));
let storyFlags = JSON.parse(localStorage.getItem('mot-story') || '{}');
let language = localStorage.getItem('mot-language') || 'id';
let graphics = localStorage.getItem('mot-graphics') || 'high';
let cameraSensitivity = Number(localStorage.getItem('mot-sensitivity') || 1);
let runHeld = false, joy = {x:0,z:0}, pointerDown = null, gameTime = 0;
const regions = [
  {name:'THE ENTRANCE',sub:'THE FIRST NIGHT',color:'#11343a',fog:'#0b2228',accent:'#83e9dc',ambient:'#a3f4e3'},
  {name:'THE LOST CITY',sub:'A TOMORROW UNBUILT',color:'#182a3a',fog:'#101b2c',accent:'#f2c98c',ambient:'#e6c998'},
  {name:'THE OCEAN MEMORY',sub:'WHERE THE BLUE REMEMBERS',color:'#092d42',fog:'#082438',accent:'#74c8ed',ambient:'#79bdeb'},
  {name:'THE SILENT PLANET',sub:'A DIFFERENT GRAVITY',color:'#302638',fog:'#211a32',accent:'#d59ef0',ambient:'#c8a9e3'},
  {name:'THE BROKEN FUTURE',sub:'ARCHIVE INSTABILITY',color:'#392624',fog:'#24171a',accent:'#ff9578',ambient:'#ffa58d'},
  {name:'THE LAST EXHIBITION',sub:'THE FIRST MEMORY',color:'#282a2b',fog:'#141a1d',accent:'#e9d8a4',ambient:'#e6d3a2'}
];
const mat = (color, roughness=.6, metalness=.1, extra={}) => new THREE.MeshStandardMaterial({color, roughness, metalness, ...extra});
const materials = {
  stone: mat('#243b3d',.72,.35), floor: mat('#172a2c',.48,.5), dark: mat('#101d21',.38,.55), gold: mat('#bca878',.3,.7),
  cyan: mat('#71dfd2',.25,.25,{emissive:'#14594f',emissiveIntensity:1.1}), white: mat('#d7ded0',.38,.15), glass: mat('#8de4d8',.22,.55,{transparent:true,opacity:.2}),
  blue: mat('#487e9a',.35,.35,{emissive:'#173b55',emissiveIntensity:.6}), coral: mat('#dd8e70',.4,.15)
};
const boxGeo = new THREE.BoxGeometry(1,1,1);
const sphereGeo = new THREE.SphereGeometry(1,24,16);
const cylinderGeo = new THREE.CylinderGeometry(1,1,1,32);
const capsuleGeo = new THREE.CapsuleGeometry(.28,.74,6,12);
const addMesh = (parent, geometry, material, pos, scale, cast=true) => {const m=new THREE.Mesh(geometry,material);m.position.set(...pos);if(scale)m.scale.set(...scale);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m;};
const addBox = (parent, material, pos, scale) => addMesh(parent,boxGeo,material,pos,scale);
const pointLight = (parent,color,intensity,pos,distance=14) => {const l=new THREE.PointLight(color,intensity,distance,2);l.position.set(...pos);parent.add(l);return l;};

function setupLights(region=0){
  scene.add(new THREE.HemisphereLight(regions[region].ambient,'#071318',2.1));
  const key=new THREE.DirectionalLight('#e4f6e8',3.3);key.position.set(-5,12,8);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-16;key.shadow.camera.right=16;key.shadow.camera.top=18;key.shadow.camera.bottom=-18;scene.add(key);
  pointLight(scene,regions[region].accent,34,[0,8,-8],30);
  pointLight(scene,'#429c9a',12,[-9,4,0],18);
}
function makeRoom(region=0){
  currentRegion=region;const info=regions[region];scene.background.set(info.fog);scene.fog.color.set(info.fog);scene.fog.density=region===2?.035:.023;setupLights(region);
  const root=new THREE.Group();scene.add(root);
  const floor=addBox(root,materials.floor,[0,-.35,0],[32,.7,36]);floor.material=mat(info.color,.5,.5);
  // Elegant museum nave: ribbed stone, glowing inlay, tall sculptural arches.
  for(let z=-15;z<=12;z+=3){
    const line=addBox(root,materials.cyan,[0,.012,z],[17,.025,.035]);line.material=materials.cyan;
    for(const x of [-8.7,8.7]){
      addBox(root,materials.stone,[x,3,z],[.65,6,.72]);
      addBox(root,materials.gold,[x,6.08,z],[.83,.12,.9]);
      const rib=addMesh(root,cylinderGeo,materials.stone,[x*1.04,7,z],[.14,8,.14]);
    }
  }
  // perimeter walls, far portal, overhead floating rings
  addBox(root,materials.dark,[-9.2,3,0],[.5,6,32]);addBox(root,materials.dark,[9.2,3,0],[.5,6,32]);
  addBox(root,materials.dark,[0,3,-17],[19,6,.5]);addBox(root,materials.dark,[0,8,-1],[18,.25,32]);
  for(let i=0;i<5;i++){
    const hoop=new THREE.Mesh(new THREE.TorusGeometry(2.4+i*.44,.035,8,90),materials.cyan);hoop.position.set((i%2?1:-1)*1.5,7.35,-4-i*2.2);hoop.rotation.x=Math.PI/2.5;root.add(hoop);
    const plinth=addMesh(root,cylinderGeo,materials.dark,[i%2?-4:4, .45, -3-i*2.5],[1.3,.9,1.3]);
    const relic=addMesh(root, i%2?sphereGeo:new THREE.OctahedronGeometry(.8,1), i%2?materials.blue:materials.gold,[i%2?-4:4,1.65,-3-i*2.5],[.72,.72,.72]);
    relic.userData.float=true;particles.push(relic);
  }
  // A surreal central sculpture: three suspended, orbiting fragments.
  const monument=new THREE.Group();monument.position.set(0,2.4,-5);root.add(monument);
  const core=addMesh(monument,new THREE.IcosahedronGeometry(1.05,1),materials.white,[0,0,0],[1,1,1]);core.material=mat('#d7e5d7',.18,.5,{emissive:'#4b7971',emissiveIntensity:.55});
  for(let i=0;i<3;i++){const shard=addMesh(monument,new THREE.TetrahedronGeometry(.68,0),i===1?materials.gold:materials.cyan,[Math.cos(i*2.1)*1.55,Math.sin(i*2.1)*1.2,0],[.8,1.2,.7]);shard.rotation.z=i*1.1;}
  // Decorative etched floor paths, wall glyphs, suspended dust motes.
  for(let i=0;i<70;i++){const p=addMesh(root,sphereGeo,materials.cyan,[THREE.MathUtils.randFloat(-8,8),THREE.MathUtils.randFloat(.3,7),THREE.MathUtils.randFloat(-15,12)],[.018,.018,.018],false);p.material=materials.cyan;particles.push(p);}
  for(let side of [-1,1]) for(let i=0;i<7;i++){
    const glyph=addBox(root,materials.gold,[side*9.03,1.6+i*.63,-13+i*3],[.03,.22,.07]);glyph.rotation.z=.25;
  }
  const portal=addPortal(root,region);
  buildTemporalObjects(root,region);
  return {root,portal};
}
function addPortal(root,region){
  const group=new THREE.Group();group.position.set(0,2.4,-14.5);root.add(group);
  const frame=addMesh(group,cylinderGeo,materials.dark,[0,0,0],[2.25,4.7,.35]);frame.rotation.z=0;
  const glow=new THREE.Mesh(new THREE.TorusGeometry(1.65,.12,12,64),materials.cyan);glow.position.z=.22;group.add(glow);
  const center=addMesh(group,new THREE.PlaneGeometry(3,4),mat(regions[(region+1)%regions.length].color,.15,.3,{emissive:regions[(region+1)%regions.length].accent,emissiveIntensity:.25,transparent:true,opacity:.75}),[0,0,.2],[1,1,1],false);
  center.userData.portal=true;center.userData.next=(region+1)%regions.length;
  const label=addBox(group,materials.gold,[0,-2.8,.25],[2.5,.04,.05]);
  return group;
}
function buildTemporalObjects(root,region){
  interactables.length=0;
  if(region===0){
    const consoleGroup=new THREE.Group();consoleGroup.position.set(-5,0,-1.7);root.add(consoleGroup);
    addMesh(consoleGroup,cylinderGeo,materials.dark,[0,.48,0],[1.05,.95,1.05]);
    addMesh(consoleGroup,cylinderGeo,materials.gold,[0,1.02,0],[.78,.18,.78]);
    const consoleCore=addMesh(consoleGroup,sphereGeo,materials.cyan,[0,1.35,0],[.34,.34,.34]);
    makeTemporal(consoleGroup,'The Meridian Engine','A museum power core with an impossible date.',[
      'Cold brass. No current passes through its veins.',
      'Dormant. The museum has forgotten its own pulse.',
      'A second heartbeat is forming in a future that should not exist.'
    ],(state)=>{consoleCore.material=state==='future'?materials.cyan:state==='past'?materials.gold:materials.blue;consoleCore.scale.setScalar(state==='future'?.48:.34);if(state==='future'&&!storyFlags.engine){storyFlags.engine=true;save();notify('MERIDIAN ENGINE — POWER RESTORED');setObjective('Read the statue’s memory');}});
    const statue=new THREE.Group();statue.position.set(5,0,-1);root.add(statue);
    const bust=addMesh(statue,new THREE.SphereGeometry(.63,20,16),materials.white,[0,1.5,0],[.72,1.18,.58]);
    addMesh(statue,cylinderGeo,materials.dark,[0,.57,0],[.8,1.15,.8]);
    const halo=new THREE.Mesh(new THREE.TorusGeometry(.92,.045,10,40),materials.gold);halo.position.set(0,2.5,0);statue.add(halo);
    makeTemporal(statue,'The Witness','A figure whose face was removed from every record.',[
      'A name is carved beneath the plinth: ILYAN. The letters are older than the museum.',
      'The face is smooth stone. A shallow groove runs from its ear to the heart.',
      'The statue is empty. Its shadow is standing somewhere else.'
    ],(state)=>{bust.material=state==='past'?materials.gold:state==='future'?materials.coral:materials.white;bust.scale.y=state==='past'?1.3:1.18;if(state==='past')statue.userData.revealed=true;});
    const bridge=new THREE.Group();bridge.position.set(0,0,-9.6);root.add(bridge);
    for(let i=0;i<7;i++){const slab=addBox(bridge,materials.blue,[-3+i, .12,0],[.88,.18,2.1]);slab.material=materials.blue;slab.visible=false;}
    const gate=new THREE.Group();gate.position.set(0,0,-13.1);root.add(gate);
    addBox(gate,materials.dark,[-2,2,0],[.45,4,.65]);addBox(gate,materials.dark,[2,2,0],[.45,4,.65]);
    const lintel=addBox(gate,materials.gold,[0,4,0],[4.4,.3,.8]);
    makeTemporal(bridge,'The Unbuilt Span','A bridge that appears only in one possible tomorrow.',[
      'No bridge was ever built. The gap is intentional.',
      'A sketch in the dust. Its first stone has not yet been laid.',
      'The span is here, borrowed from an unchosen future.'
    ],(state)=>{bridge.children.slice(0,7).forEach((m,i)=>{m.visible=state==='future';m.position.y=state==='future'?.13+Math.sin(gameTime+i)*.04:.12;});bridge.userData.active=state==='future';if(state==='future'&&!storyFlags.span){storyFlags.span=true;save();notify('A FUTURE TAKES SHAPE');setObjective('Find the Witness’s hidden memory');}});
    registerInteract('Meridian Engine',consoleGroup,1.7,()=>openTimeline(consoleGroup));
    registerInteract('The Witness',statue,1.9,()=>openTimeline(statue));
    registerInteract('Unbuilt Span',bridge,2,()=>openTimeline(bridge));
    registerInteract('Echo Terminal',null,2.1,()=>openEcho(),new THREE.Vector3(0,0,7));
    registerInteract('Exhibition Gate',gate,2,()=>{if(artifacts.has('first-light')&&storyFlags.engine&&storyFlags.span){notify('THE LAST EXHIBITION IS OPEN');changeRegion(5);}else{notify('THE GATE REQUIRES THREE TEMPORAL IMPRESSIONS');}});
    // Gold fragments are the three story artifacts: one is awarded by the witness, two lie in the nave.
    for(let i=0;i<2;i++){
      const pos=i===0?new THREE.Vector3(-7,1.1,6):new THREE.Vector3(7,1.1,7);
      const shard=addMesh(root,new THREE.OctahedronGeometry(.27,0),materials.gold,[pos.x,pos.y,pos.z],[1,1,1]);shard.userData.float=true;
      registerInteract(i===0?'Loose memory':'Uncatalogued fragment',shard,1.3,()=>collectArtifact(i===0?'quiet':'visitor',shard));
    }
    registerInteract('Witness memory',null,1.8,()=>{
      if(!statue.userData.revealed){notify('THE WITNESS IS HIDING SOMETHING');return;}
      if(!artifacts.has('first-light'))collectArtifact('first-light',null);
      storyFlags.witness=true;save();setObjective('Open the exhibition gate');
    },new THREE.Vector3(5,1.5,-1));
  } else {
    const artifactNames=['City seed','Ocean memory','Planetary lens','Broken hour','Origin fragment'];
    for(let i=0;i<5;i++){
      const p=new THREE.Vector3((i%2?1:-1)*4,.9,-2-i*2.1);
      const g=addMesh(root,new THREE.DodecahedronGeometry(.48,0),i%2?materials.gold:materials.cyan,[p.x,p.y,p.z],[1,1,1]);g.userData.float=true;
      registerInteract(artifactNames[region-1]||'Exhibition fragment',g,1.6,()=>collectArtifact(`region-${region}`,g));
    }
    registerInteract('Archive echo',null,2,()=>openEcho(),new THREE.Vector3(0,0,6));
  }
}
function makeTemporal(group,name,description,states,onChange){group.userData.temporal={name,description,states,current:'present',onChange};}
function registerInteract(name,object,radius,action,position){interactables.push({name,object,radius,action,position:position||null});}
function worldPosition(item){if(item.position)return item.position;const v=new THREE.Vector3();item.object.getWorldPosition(v);return v;}

// The player is a small, deliberately stylized museum keeper silhouette.
const avatar=new THREE.Group();
const body=addMesh(avatar,capsuleGeo,mat('#d0d7cb',.6,.15),[0,1,0],[1,1,1]);
const head=addMesh(avatar,sphereGeo,mat('#d8cbb1',.55,.1),[0,1.78,0],[.23,.25,.23]);
const visor=addMesh(avatar,new THREE.SphereGeometry(.205,20,12),mat('#203b3d',.17,.65,{emissive:'#174a4d',emissiveIntensity:.3}),[0,1.81,-.08],[1,.68,.5]);
const pack=addBox(avatar,mat('#59766f',.55,.4),[0,1.12,.25],[.38,.49,.16]);avatar.add(body,head,visor,pack);scene.add(avatar);

let world = makeRoom(0);
function save(){localStorage.setItem('mot-artifacts',JSON.stringify([...artifacts]));localStorage.setItem('mot-story',JSON.stringify(storyFlags));localStorage.setItem('mot-region',String(currentRegion));}
function collectArtifact(id,object){if(artifacts.has(id)){notify('MEMORY ALREADY ARCHIVED');return;}artifacts.add(id);if(object)object.visible=false;save();updateArtifactCount();notify('ARTIFACT RECOVERED · '+(artifacts.size).toString().padStart(2,'0'));if(artifacts.size>=3&&currentRegion===0)setObjective('Open the exhibition gate');}
function updateArtifactCount(){ui.artifactCount.textContent=`${String(artifacts.size).padStart(2,'0')} / 03`;}
function setObjective(text){ui.objective.textContent=text;}
let toastTimer;
function notify(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2400);}
function openTimeline(item){const temporal=item.userData.temporal;if(!temporal){notify('NO TEMPORAL SIGNATURE');return;}activeTarget=item;ui.timelineObject.textContent=temporal.name.toUpperCase();ui.timeDescription.textContent=temporal.states[['past','present','future'].indexOf(temporal.current)];ui.timeline.classList.remove('hidden');ui.hud.classList.add('timeline-open');document.querySelectorAll('.time-rail button').forEach(b=>b.classList.toggle('selected',b.dataset.time===temporal.current));}
function closeTimeline(){ui.timeline.classList.add('hidden');ui.hud.classList.remove('timeline-open');}
function setTime(state){if(!activeTarget?.userData.temporal)return;const t=activeTarget.userData.temporal;t.current=state;ui.timeDescription.textContent=t.states[['past','present','future'].indexOf(state)];document.querySelectorAll('.time-rail button').forEach(b=>b.classList.toggle('selected',b.dataset.time===state));t.onChange?.(state);playTemporalSound();}
function playTemporalSound(){try{const ac=new AudioContext(),o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.setValueAtTime(190,ac.currentTime);o.frequency.exponentialRampToValueAtTime(650,ac.currentTime+.18);g.gain.setValueAtTime(.08,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.55);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+.56);}catch{}}
function openEcho(){dialogueOpen=true;ui.dialogue.classList.remove('hidden');ui.speaker.textContent='ECHO / MUSEUM INTELLIGENCE';ui.dialogueText.textContent=language==='id'?'Selamat malam, Arka. Pusat pameran telah hilang. Aneh—catatan menunjukkan benda itu belum pernah ada. Apa yang ingin kau tanyakan?':'Good evening, Arka. The centrepiece is missing. Strange—our records insist it never existed. What would you like to ask?';ui.choices.innerHTML='';[['About the missing object','I was built to preserve possibilities. I cannot explain why this one is disappearing.'],['Who built this place?','The architect is listed as Ilyan. Every record of their face has been removed.'],['What are you hiding?','I am not hiding anything. I am… omitting a memory I cannot bear to lose.']].forEach(([label,response])=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>{ui.dialogueText.textContent=response;ui.choices.innerHTML='';const c=document.createElement('button');c.textContent='I understand.';c.onclick=closeEcho;ui.choices.append(c);storyFlags.echoSeen=true;save();};ui.choices.append(b);});}
function closeEcho(){dialogueOpen=false;ui.dialogue.classList.add('hidden');}
function changeRegion(index){if(index===currentRegion)return;scene.remove(world.root);while(scene.children.length){const child=scene.children[0];if(child===avatar){break;}scene.remove(child);}interactables.length=0;particles.length=0;world=makeRoom(index);player.pos.set(0,0,6);player.yaw=Math.PI;setObjective(index===0?'Find the missing centrepiece':`Recover a memory in ${regions[index].name.toLowerCase()}`);document.querySelector('.hud-brand b').textContent=regions[index].name;document.querySelector('.hud-brand small').innerHTML=`WING 0${index+1} <i>—</i> ${regions[index].sub}`;save();notify(`ENTERING ${regions[index].name}`);}

